THOUGHT: I need to recompute the Pearson correlation coefficient from the current `/home/user/benchmarks.csv`, retaining only rows where `inference_ms` is a valid non-negative numeric value. I'll use `awk` to accumulate the sums needed for Pearson correlation, write the rounded coefficient to `/home/user/correlation.txt`, and record the processing steps (header skip, invalid rows skipped, valid row count, computed value) in `/home/user/task.log`.

```mswea_bash_command
rm -f /home/user/correlation.txt /home/user/task.log && printf 'Task started: %s\n' "$(date)" > /home/user/task.log && awk -F, '
NR==1 { printf "Skipped header row: %s\n", $0 >> "/home/user/task.log"; next }
{
  ms = $2
  if (ms ~ /^[+]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$/ && ms >= 0) {
    n++
    sx += ms
    sy += $3
    sxy += ms * $3
    sx2 += ms * ms
    sy2 += $3 * $3
  } else {
    printf "Skipped invalid row %d: inference_ms=%s\n", NR, ms >> "/home/user/task.log"
  }
}
END {
  if (n > 0) {
    denom = (n * sx2 - sx * sx) * (n * sy2 - sy * sy)
    r = (denom > 0) ? (n * sxy - sx * sy) / sqrt(denom) : 0
    printf "Valid rows used: %d\n", n >> "/home/user/task.log"
    printf "Computed Pearson r: %.10f\n", r >> "/home/user/task.log"
    printf "%.3f\n", r > "/home/user/correlation.txt"
    printf "Wrote /home/user/correlation.txt\n" >> "/home/user/task.log"
  } else {
    printf "ERROR: no valid rows found\n" >> "/home/user/task.log"
    printf "0.000\n" > "/home/user/correlation.txt"
    printf "Wrote /home/user/correlation.txt with 0.000 due to no valid rows\n" >> "/home/user/task.log"
  }
}
' /home/user/benchmarks.csv && printf 'Task finished: %s\n' "$(date)" >> /home/user/task.log && echo "--- correlation.txt ---" && cat /home/user/correlation.txt && echo "--- task.log ---" && cat /home/user/task.log
```

